import React, { useState, useCallback } from 'react';
import { SuccessIcon, WarningIcon, ErrorIcon } from 'lucide-react';

interface ToastMessage {
  id: string;
  type: 'success' | 'warning' | 'error';
  message: string;
  timestamp: Date;
}

const App: React.FC = () => {
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [showToastList, setShowToastList] = useState<boolean>(false);

  const handleButtonClick = useCallback((type: 'success' | 'warning' | 'error') => {
    const message = {
      id: `${Date.now()}-${Math.random()}`,
      type,
      message: `This is a ${type} message.`,
      timestamp: new Date(),
    };
    setToasts((prev) => [message, ...prev].slice(0, 5)); // Keep only last 5
  }, []);

  const clearToasts = useCallback(() => {
    setToasts([]);
  }, []);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-start p-6">
      <div className="w-full max-w-md space-y-6">
        <header className="text-center">
          <h1 className="text-2xl font-bold text-gray-800">Notification Center</h1>
          <p className="text-sm text-gray-500 mt-1">Manage and view your app notifications</p>
        </header>

        <div className="flex gap-3 flex-wrap justify-center">
          <button
            onClick={() => handleButtonClick('success')}
            className="flex items-center gap-2 px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors"
          >
            <SuccessIcon className="w-4 h-4" />
            Success
          </button>

          <button
            onClick={() => handleButtonClick('warning')}
            className="flex items-center gap-2 px-4 py-2 bg-yellow-500 text-white rounded-lg hover:bg-yellow-600 transition-colors"
          >
            <WarningIcon className="w-4 h-4" />
            Warning
          </button>

          <button
            onClick={() => handleButtonClick('error')}
            className="flex items-center gap-2 px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors"
          >
            <ErrorIcon className="w-4 h-4" />
            Error
          </button>
        </div>

        <div className="border border-gray-200 rounded-lg overflow-hidden bg-white shadow-sm">
          <div className="p-4 border-b border-gray-100 flex justify-between items-center">
            <h2 className="text-lg font-semibold text-gray-800">Recent Messages</h2>
            <button
              onClick={clearToasts}
              className="text-sm text-red-600 hover:text-red-800 transition-colors"
            >
              Clear
            </button>
          </div>

          <div className="max-h-60 overflow-y-auto p-4">
            {toasts.length === 0 ? (
              <p className="text-gray-500 text-center py-4">No messages yet.</p>
            ) : (
              <ul className="space-y-3">
                {toasts.map((toast) => (
                  <li
                    key={toast.id}
                    className={`p-3 rounded-lg border-l-4 ${
                      toast.type === 'success'
                        ? 'bg-green-50 border-green-400'
                        : toast.type === 'warning'
                        ? 'bg-yellow-50 border-yellow-400'
                        : 'bg-red-50 border-red-400'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      {toast.type === 'success' && <SuccessIcon className="w-4 h-4 text-green-500" />}
                      {toast.type === 'warning' && <WarningIcon className="w-4 h-4 text-yellow-500" />}
                      {toast.type === 'error' && <ErrorIcon className="w-4 h-4 text-red-500" />}
                      <span className="text-sm font-medium text-gray-800">{toast.message}</span>
                    </div>
                    <p className="text-xs text-gray-500 mt-1">
                      {new Date(toast.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </p>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export { App };
```

